/**
 * Roster oficial de jugadores del Mundial 2026 (Balon de Oro).
 *
 * Fuente: lista oficial de convocados FIFA (SquadLists, 1 jun 2026).
 * 48 selecciones x 26 jugadores = 1248 jugadores. Es la fuente de verdad
 * del front y backend para la eleccion del mejor jugador.
 *
 * Reglas:
 *   - `playerId` es un slug estable derivado del nombre. Para los jugadores
 *     que ya existian en el roster mock anterior se preservo el id original
 *     (evita huerfanar picks ya realizados).
 *   - `teamId` sigue el fifaCode de `team-identity.ts`.
 *   - `position` es informativa para la UI (chip): GK/DEF/MID/FWD.
 *   - `club` y `name` se toman verbatim del documento oficial FIFA
 *     (algunos apellidos vienen sin diacriticos en la fuente).
 *
 * Generado desde scripts/_gen_roster.py (one-shot).
 */

export type BestPlayerPosition = "GK" | "DEF" | "MID" | "FWD";

export type BestPlayerRosterEntry = {
  playerId: string;
  name: string;
  teamId: string;
  position: BestPlayerPosition;
  club: string;
};

